theme.css:
/* theme: Fiscal Reckoning | Brazil's market shock and China's AI rout set the tone — a day of correction, where old certainties unwind and numbers rule. */
/* layout: hero=split; political-news=numbered/grid-2; financial-news=stat/grid-3; entertainment-news=tile/masonry; music-releases=plain/stack; stock-analysis=stat/grid-3; outlook=timeline/stack */

.diary-page {
  --paper: #101418;
  --paper-alt: #1a2026;
  --ink: #f4f6f8;
  --ink-soft: #c8d0d6;
  --muted: #a0aab0;
  --accent: #ff6f5a;
  --accent-ink: #1a0e0c;
  --rule: #2e383f;
  --font-display: var(--ff-bebas), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-inter), system-ui, sans-serif;
}

.diary-page .diary-hero {
  background: var(--paper);
  border-bottom: 2px solid var(--accent);
}

.diary-page .diary-hero-inner {
  padding-block: 2rem 3rem;
}

.diary-page .diary-kicker {
  font-family: var(--font-ui);
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--accent);
}

.diary-page .diary-title {
  font-family: var(--font-display);
  font-size: clamp(3.5rem, 8vw, 6.5rem);
  font-weight: 400;
  letter-spacing: 0.02em;
  line-height: 0.95;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-summary {
  font-family: var(--font-body);
  font-size: clamp(1.1rem, 1.8vw, 1.35rem);
  line-height: 1.65;
  color: var(--ink-soft);
  border-left: 3px solid var(--accent);
  padding-left: 1.25rem;
}

.diary-page .diary-theme-note {
  font-family: var(--font-ui);
  font-size: 0.9rem;
  line-height: 1.6;
  color: var(--muted);
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.75rem;
  padding: 0.2rem 0.7rem;
}

.diary-page .diary-crumbs a {
  color: var(--muted);
  font-size: 0.8rem;
}

.diary-page .diary-crumbs a:hover {
  color: var(--accent);
}

.diary-page .diary-body {
  padding-bottom: 5rem;
}

.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-toc-label {
  color: var(--muted);
  font-weight: 700;
}

.diary-page .diary-toc-link {
  color: var(--muted);
  font-size: 0.8rem;
  font-weight: 600;
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-toc-number {
  color: var(--accent);
}

.diary-page .diary-toc-top {
  color: var(--muted);
}

.diary-page .diary-toc-top:hover {
  color: var(--accent);
}

.diary-page .diary-section {
  border-top: 1px solid var(--rule);
  padding-block: 2.5rem;
}

.diary-page .diary-section:first-child {
  border-top: 0;
}

.diary-page .diary-section-head {
  border-bottom: 2px solid var(--ink);
  padding-bottom: 0.75rem;
  margin-bottom: 1.75rem;
}

.diary-page .diary-section-number {
  font-family: var(--font-ui);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--accent);
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 400;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-prose {
  font-size: 1.08rem;
  line-height: 1.7;
  color: var(--ink-soft);
}

.diary-page .diary-prose h3 {
  font-family: var(--font-ui);
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-prose h4 {
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 400;
  letter-spacing: 0.02em;
  color: var(--ink);
}

.diary-page .diary-prose a {
  font-family: var(--font-ui);
  font-size: 0.7em;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--accent);
  border-bottom: 1px solid var(--accent);
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
  font-weight: 700;
}

.diary-page .diary-prose blockquote {
  border-left: 3px solid var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.8rem;
  font-weight: 400;
  letter-spacing: 0.02em;
  line-height: 1.1;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-card-body {
  font-size: 1.08rem;
  line-height: 1.7;
  color: var(--ink-soft);
}

.diary-page .diary-card-thread {
  border: 1px solid var(--accent);
  color: var(--accent);
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page .diary-card--numbered .diary-card-inner {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  column-gap: 1rem;
  row-gap: 0.5rem;
  align-content: start;
  padding-top: 0.75rem;
  border-top: 1px solid var(--rule);
}

.diary-page .diary-card--numbered .diary-card-index {
  grid-row: 1 / span 3;
  font-family: var(--font-display);
  font-size: 2.8rem;
  font-weight: 400;
  line-height: 0.85;
  color: var(--accent);
}

.diary-page .diary-card--numbered .diary-card-inner > :not(.diary-card-index) {
  grid-column: 2;
}

.diary-page .diary-card--stat .diary-card-inner {
  padding-top: 0.75rem;
  border-top: 2px solid var(--accent);
}

.diary-page .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 12cqi, 4rem);
  font-weight: 400;
  line-height: 1;
  letter-spacing: 0.02em;
  color: var(--accent);
}

.diary-page .diary-card--tile .diary-card-inner {
  padding: 1.25rem;
  background: var(--paper-alt);
  border: 1px solid var(--rule);
}

.diary-page .diary-card--tile .diary-card-title {
  font-size: 1.6rem;
}

.diary-page .diary-card--timeline .diary-card-inner {
  padding-left: 1.75rem;
}

.diary-page .diary-card--timeline .diary-card-inner::before {
  background: var(--rule);
}

.diary-page .diary-card--timeline .diary-card-inner::after {
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper);
}

.diary-page .diary-card--outline .diary-card-inner {
  border: 1px solid var(--rule);
  border-radius: 0;
  padding: 1.25rem;
}

.diary-page .diary-card--elevated .diary-card-inner {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-radius: 0;
  box-shadow: 0 2px 4px rgb(0 0 0 / 0.3), 0 8px 24px -8px rgb(0 0 0 / 0.5);
  padding: 1.25rem;
}

.diary-page .diary-card--banner .diary-card-inner {
  border: 1px solid var(--rule);
  border-radius: 0;
}

.diary-page .diary-card--banner .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
  padding: 0.75rem 1rem;
  font-size: 1.5rem;
}

.diary-page .diary-card--banner .diary-card-body {
  padding: 1rem;
}

.diary-page .diary-card--split .diary-card-inner {
  border-top: 2px solid var(--ink);
  padding-top: 1rem;
}

.diary-page .diary-card-lede {
  border-left: 3px solid var(--accent);
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 400;
  line-height: 1.3;
  color: var(--ink);
  padding-left: 0.75rem;
}

.diary-page .diary-stories--stack .diary-card-body {
  font-size: 1.15rem;
  line-height: 1.75;
}

.diary-page .diary-stories--stack > .diary-card--plain + .diary-card--plain {
  border-top: 1px solid var(--rule);
}

.diary-page .diary-markets-wrap {
  margin-bottom: 2rem;
}

.diary-page .diary-markets-label {
  color: var(--muted);
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.diary-page .diary-markets {
  gap: 0.75rem;
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  padding: 0.75rem;
  font-family: var(--font-ui);
}

.diary-page .diary-spark-label {
  color: var(--muted);
  font-size: 0.75rem;
}

.diary-page .diary-spark-value {
  color: var(--ink);
  font-size: 0.95rem;
  font-weight: 700;
}

.diary-page .diary-spark-change {
  font-size: 0.75rem;
  font-weight: 700;
}

.diary-page .diary-spark.is-up {
  color: #7ed07e;
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

.diary-page .diary-spark .diary-spark-line polyline {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
}

.diary-page .diary-footer {
  border-top: 1px solid var(--rule);
  color: var(--muted);
  font-family: var(--font-ui);
  font-size: 0.875rem;
}

.diary-page .diary-footer a {
  color: var(--ink);
  font-weight: 700;
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

@media (min-width: 1024px) {
  .diary-page[data-hero="split"] .diary-hero-inner {
    grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr);
    column-gap: 4rem;
  }

  .diary-page .diary-toc {
    top: 2rem;
    margin-top: 3rem;
  }

  .diary-page .diary-toc-list {
    border-left: 1px solid var(--rule);
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}
